/* 20 selection actions */
.sel-p{padding:20px 18px 6px;font-size:15px;line-height:1.75;position:relative}
.sent{cursor:text;transition:background-color .3s,color .3s;padding:2px 0}
.sent:hover{background:rgba(var(--fg-rgb),.04)}
.sent.picked{background:rgba(255,133,13,.16);color:var(--text)}
.sel-bar{position:absolute;z-index:4;display:flex;background:var(--panel);border:1px solid var(--icon-line);opacity:0;transform:translateY(4px);transition:opacity .2s ease,transform .3s var(--ease);pointer-events:none;white-space:nowrap}
.sel-bar.show{opacity:1;transform:none;pointer-events:auto}
.sel-bar button{display:inline-flex;align-items:center;gap:5px;padding:6px 8px;font-size:11.5px;font-weight:600;color:var(--text-dim);border-right:1px solid var(--line);transition:color .2s,background-color .2s}
.sel-bar button:last-child{border-right:0}
.sel-bar button:hover{color:var(--accent);background:var(--accent-bg)}
.sel-bar .ms{font-size:14px}
.explain{margin:4px 18px 16px;padding:10px 12px;border-left:2px solid var(--accent);font-size:13px;line-height:1.6;color:var(--text-dim)}
.sel-hint{padding:0 18px 16px}

/* rewrite toolbar: edit field, two actions and a chevron that slides out the rest */
.sel-bar{display:flex;align-items:center;height:44px;padding:0 4px 0 6px;overflow:hidden;white-space:nowrap;transition:opacity .2s ease,transform .3s var(--ease),width .5s var(--ease),left .5s var(--ease)}
.sel-view{flex:1;min-width:0;height:100%;overflow:hidden}
.sel-track{display:flex;align-items:center;gap:2px;height:100%;transition:transform .5s var(--ease)}
.sel-inw{flex:none;width:150px;display:flex;align-items:center;padding:0 8px;transition:opacity .3s ease}
.sel-bar.exp .sel-inw,.sel-bar.exp .sel-div{opacity:0}
.sel-inw input{width:100%;background:transparent;border:0;outline:0;font:inherit;font-size:13px;color:var(--text)}
.sel-inw input::placeholder{color:var(--muted)}
.sel-div{flex:none;width:1px;height:20px;margin:0 4px;background:var(--line);transition:opacity .3s ease}
.sel-acts{display:flex;gap:2px;flex:none}
.sel-bar .sel-acts button{display:inline-flex;align-items:center;gap:6px;height:34px;padding:0 10px;border:0;font-size:13px;font-weight:500;color:var(--text-dim);transition:color .2s,background-color .2s}
.sel-bar .sel-acts button:hover{color:var(--text);background:var(--chip)}
.sel-bar .sel-more{flex:none;width:32px;height:32px;padding:0;display:grid;place-items:center;border:0;border-left:0;color:var(--muted)}
.sel-bar .sel-more .ms{transition:transform .45s var(--ease)}
.sel-bar.exp .sel-more .ms{transform:rotate(180deg)}
.sel-bar .sel-more:hover{color:var(--text)}
[data-style="soft"] .sel-bar{border-radius:999px;padding:0 4px 0 8px}
[data-style="soft"] .sel-bar .sel-acts button{border-radius:999px}
[data-style="soft"] .sel-bar .sel-more{border-radius:50%}
[data-style="soft"] .sent.picked{background:rgba(17,111,248,.12);box-shadow:none;border:0;outline:0}
@media (prefers-color-scheme: dark){ [data-style="soft"]:not([data-theme="light"]) .sent.picked{background:rgba(47,128,255,.24)} }
[data-style="soft"][data-theme="dark"] .sent.picked{background:rgba(47,128,255,.24)}

/* ---------- 20 selection actions ---------- */
{
  const p = $('#sel-p'), bar = $('#sel-bar'), panel = $('#sel-panel'), ex = $('#sel-ex'), exT = $('#sel-ex-t');
  const track = $('#sel-track'), more = $('#sel-more'), inp = $('#sel-in'), inw = $('.sel-inw', bar), div = $('.sel-div', bar), acts = $('.sel-acts', bar);
  const base = [
    'The pricing page loads in under two seconds on desktop.',
    'Most visitors scroll past the plans before they reach the comparison table, which means the table rarely gets read by anyone.',
    'Moving it above the plans would put the details people ask about in front of them first.'
  ];
  const alt = {
    improve:['The pricing page loads in under two seconds on desktop, so speed is not the issue.','Most visitors scroll past the plans and never reach the comparison table.','Placing the table above the plans answers the common questions up front.'],
    shorten:['Pricing loads in under two seconds.','Most visitors never reach the comparison table.','Move the table above the plans.'],
    tone:['Good news, the pricing page loads in under two seconds on desktop.','A lot of visitors scroll past the plans before they get to the comparison table.','Popping it above the plans would show people the details they look for first.'],
    grammar:['The pricing page loads in under two seconds on desktop.','Most visitors scroll past the plans before they reach the comparison table, so the table rarely gets read.','Moving it above the plans would put the details people ask about in front of them first.']
  };
  const explain = [
    'Load time is measured on a fast connection, so this rules out speed as the reason people leave the page.',
    'Scroll depth data shows where attention drops off, and the comparison table sits below that point.',
    'Putting answers before the plans reduces back-and-forth, since visitors see the detail before choosing.'
  ];
  let txt = base.slice(), pick = -1, expanded = false, anchor = null;
  function render(){ p.innerHTML = txt.map((t, i) => `<span class="sent" data-i="${i}">${t}</span>`).join(' '); }
  // collapsed shows the edit field plus two actions, expanded slides the field away and shows every action
  const IN_W = 140 + 9, view = $('.sel-view', bar);
  function size(){
    const btns = $$('button', acts), pad = 12, chev = more.offsetWidth || 34;
    return { collapsed: pad + IN_W + btns[0].offsetWidth + btns[1].offsetWidth + 2 + chev, full: pad + acts.scrollWidth + chev };
  }
  function layout(){
    // never wider than the card, the rest scrolls sideways
    const pr = panel.getBoundingClientRect(), z = size(), w = Math.min(expanded ? z.full : z.collapsed, pr.width - 16);
    bar.style.width = w + 'px';
    if (anchor){
      const r = anchor.getBoundingClientRect();
      bar.style.left = Math.max(8, Math.min(pr.width - w - 8, r.left - pr.left)) + 'px';
      bar.style.top = (r.bottom - pr.top + 8) + 'px';
    }
  }
  function open(span){ anchor = span; expanded = false; bar.classList.remove('exp'); bar.classList.add('show'); view.scrollLeft = 0; layout(); }
  function hide(){ bar.classList.remove('show', 'exp'); expanded = false; anchor = null; }
  p.addEventListener('click', e => {
    const s = e.target.closest('.sent'); if (!s) return;
    pick = +s.dataset.i; $$('.sent', p).forEach(x => x.classList.toggle('picked', x === s));
    open(s); Sound.play('select');
  });
  more.addEventListener('click', () => { expanded = !expanded; bar.classList.toggle('exp', expanded); view.scrollTo({ left:0, behavior:'smooth' }); layout(); Sound.play(expanded ? 'open' : 'close'); });
  addEventListener('resize', () => { if (anchor) layout(); });
  document.addEventListener('pointerdown', e => { if (anchor && !bar.contains(e.target) && !e.target.closest('#sel-p .sent')){ hide(); $$('.sent', p).forEach(x => x.classList.remove('picked')); pick = -1; } });
  function apply(a){
    if (pick < 0) return;
    hide();
    if (a === 'explain'){ exT.textContent = explain[pick]; morph(panel, () => ex.classList.add('open')); Sound.play('open'); return; }
    txt[pick] = alt[a][pick];
    const s = $(`.sent[data-i="${pick}"]`, p);
    morph(panel, () => { s.innerHTML = wordsHTML(txt[pick]); });
    revealWords(s, 35, i => { if (i % 3 === 0) Sound.play('stream'); });
    setTimeout(() => s.classList.remove('picked'), 900); pick = -1;
    Sound.play('pop');
  }
  acts.addEventListener('click', e => { const b = e.target.closest('button'); if (b) apply(b.dataset.a); });
  inp.addEventListener('keydown', e => {
    if (e.key === 'Enter' && inp.value.trim()){ e.preventDefault(); showToast('Editing: ' + inp.value.trim()); inp.value = ''; apply('improve'); }
    else if (e.key === 'Escape') hide();
  });
  $('#sel-reset').addEventListener('click', () => { txt = base.slice(); morph(panel, () => { render(); ex.classList.remove('open'); }); hide(); Sound.play('tab'); });
  render();
}
